 function esc(s){return String(s).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});}
 function fmt(a){return Array.isArray(a)?a.map(fmt).join('; '):typeof a==='object'?M.fmt(a):String(a);}
