 function courseLinks(){return '<div class="grid">'+C.paths.map(function(p){var done=p.ids.filter(function(id){return state.skills[id]&&state.skills[id].checks.length>=2;}).length;return '<a class="card" href="#course/'+p.id+'"><span class="badge">'+p.ids.length+' тем</span><h2>'+esc(p.title)+'</h2><p>'+esc(p.about)+'</p><p class="tiny">Два самостоятельных успеха: '+done+' / '+p.ids.length+'</p></a>';}).join('')+'</div>';}
 function courses(){main.innerHTML='<p class="eyebrow">Один навык — разные маршруты</p><h1>Выбери свой курс</h1><p class="lead">По классу, по теме или для восстановления основы. Можно начать с диагностики и вернуться к одному пробелу.</p><p class="tiny">Это рабочие учебные маршруты. Отдельные типы задач ещё расширяются; полное совпадение со всеми параграфами учебников не заявляется.</p>'+courseLinks()+'<section class="panel section"><h2>Геометрия: строить и доказывать</h2><div class="row"><a href="../geometry-course/index.html">Атанасян 7–9</a><a href="../stereo-course/index.html">Атанасян 10–11 · объёмные модели</a><a href="../geometry-merzlyak/index.html">Мерзляк 7–9</a><a href="../geometry-pogorelov/index.html">Погорелов 7–9</a></div><p>В этих мастерских — построения, доказательства и собственный прогресс.</p></section><section class="panel section"><h2>Целевые мастерские</h2><div class="row"><a href="../equations/index.html">Уравнения со 2 класса</a><a href="../ege-baza/percent/index.html">Проценты и части</a><a href="../ege-baza/work-rate/index.html">Землекопы без x</a><a href="../trainers/oge-basics/multiplication-division/division-lab.html">Деление уголком</a><a href="../ege-baza/index.html">ЕГЭ база</a></div></section>';}
