 function course(id){var p=C.pathById[id];if(!p)return courses();if(p.id==='makarychev9'&&p.fullCourse)return m9Course(p);if(p.id==='vilenkin5'&&p.fullCourse)return v5Course(p);if(p.fullCourse)return v6Course(p);selectCourse(id);var next=nextSkill(),complete=p.ids.every(function(k){return state.skills[k]&&state.skills[k].checks.length>=2;});main.innerHTML='<a href="#courses">← Все курсы</a><p class="eyebrow section">Учебный маршрут</p><h1>'+esc(p.title)+'</h1><p class="lead">'+esc(p.about)+'</p><section class="panel featured"><h2>'+(complete?'Повторить после завершения проверок: ':'Следующий шаг: ')+esc(C.byId[next].title)+'</h2><p>Разбор → тренировка → три самостоятельные задачи. Два успеха с первой попытки без помощи переводят рекомендацию к следующему навыку.</p><div class="row">'+button('Продолжить','learn',next)+' '+button('Определить пробелы','course-diagnostic',id,'quiet')+'</div></section>'+p.stages.map(function(g){return '<section class="section"><h2>'+esc(g.title)+'</h2><div class="skill-list">'+g.ids.map(skillRow).join('')+'</div></section>';}).join('')+(p.exactEdition?'<p class="tiny">Порядок пунктов сверён с указанным изданием. Упражнения авторские: это не банк решений всех номеров учебника.</p>':'<p class="tiny">Порядок — авторский маршрут общих навыков. Геометрия доступна на странице всех курсов.</p>')+boardLink('#course/'+id);}
